    turn_spacing = float(params['turn_spacing'])
    num_turns = float(params['num_turns'])

    grid = np.zeros((n, n), dtype=bool)

    i0, i1, j0, j1 = chip
    ci = (i0 + i1) / 2.0
    cj = (j0 + j1) / 2.0

    max_r = math.hypot(n/2 - ci, n/2 - cj)
    if max_r <= 0:
        return grid

    total_length = 0.0
    r = start_radius
    dr_per_turn = turn_spacing / (2 * math.pi)
    turns_done = 0.0

    while turns_done < num_turns and r <= max_r:
        theta = 0.0
        dtheta = 0.2
        while theta < 2 * math.pi and turns_done < num_turns:
            x = ci + r * math.cos(theta)
            y = cj + r * math.sin(theta)
            i = int(round(x))
            j = int(round(y))

            if 0 <= i < n and 0 <= j < n:
                di_range = range(max(0, i-1), min(n, i+2))
                dj_range = range(max(0, j-1), min(n, j+2))
                for ii in di_range:
                    for jj in dj_range:
                        grid[ii, jj] = True

            theta += dtheta
            r += dr_per_turn * dtheta / (2 * math.pi)
            turns_done = (r - start_radius) / turn_spacing

    material_count = np.sum(grid)
    if material_count > 1440:
        scale = math.sqrt(1440 / material_count) if material_count > 0 else 0
        if scale > 0:
            new_grid = np.zeros_like(grid)
            coords = np.argwhere(grid)
            if len(coords) > 0:
                center_i, center_j = ci, cj
                rel_coords = coords - [center_i, center_j]
                scaled_coords = (rel_coords * scale + [center_i, center_j]).round().astype(int)
                valid = (scaled_coords[:, 0] >= 0) & (scaled_coords[:, 0] < n) & \
                        (scaled_coords[:, 1] >= 0) & (scaled_coords[:, 1] < n)
                valid_coords = scaled_coords[valid]
                new_grid[valid_coords[:, 0], valid_coords[:, 1]] = True
                # Ensure chip region remains material
                new_grid[i0:i1+1, j0:j1+1] = True
                grid = new_grid

    # Final connectivity enforcement via flood fill from chip
