    labeled, _ = scipy.ndimage.label(grid, structure=[[0,1,0],[1,1,1],[0,1,0]]) if False else (None, None)
    # Since scipy not allowed, implement BFS
    from collections import deque
    visited = np.zeros_like(grid, dtype=bool)
    q = deque()
    for i in range(i0, i1+1):
        for j in range(j0, j1+1):
            if grid[i, j]:
                q.append((i, j))
                visited[i, j] = True

    while q:
        i, j = q.popleft()
        for di, dj in [(0,1),(0,-1),(1,0),(-1,0)]:
            ni, nj = i+di, j+dj
            if 0 <= ni < n and 0 <= nj < n and grid[ni, nj] and not visited[ni, nj]:
                visited[ni, nj] = True
                q.append((ni, nj))

    grid &= visited
    grid[i0:i1+1, j0:j1+1] = True  # Ensure chip stays

    # Enforce minimum 2-cell width by dilation then erosion (2 iterations)
    def binary_dilation(mask, iterations=1):
        for _ in range(iterations):
            dilated = np.zeros_like(mask)
            for i in range(n):
                for j in range(n):
                    if mask[i, j]:
                        for di in (-1,0,1):
                            for dj in (-1,0,1):
                                ni, nj = i+di, j+dj
                                if 0 <= ni < n and 0 <= nj < n:
                                    dilated[ni, nj] = True
            mask = dilated
        return mask

    def binary_erosion(mask, iterations=1):
        for _ in range(iterations):
            eroded = np.zeros_like(mask)
            for i in range(n):
                for j in range(n):
                    if mask[i, j]:
                        all_neighbors = True
                        for di in (-1,0,1):
                            for dj in (-1,0,1):
                                ni, nj = i+di, j+dj
                                if 0 <= ni < n and 0 <= nj < n:
                                    if not mask[ni, nj]:
                                        all_neighbors = False
                                        break
                            if not all_neighbors:
                                break
                        if all_neighbors:
                            eroded[i, j] = True
            mask = eroded
        return mask

    try:
        dilated = binary_dilation(grid, 2)
        eroded = binary_erosion(dilated, 2)
        grid = eroded
