                if 0 <= ni < n and 0 <= nj < n and grid[ni, nj] and not visited[ni, nj]:
                    visited[ni, nj] = True
                    q.append((ni, nj))
        grid &= visited
        grid[i0:i1+1, j0:j1+1] = True
    except:
        pass  # Fallback to current grid if morphology fails

    return grid

import numpy as np
import math

def generate(params, n, chip):
    p = {k: int(v) if k != 'width_taper' else float(v) for k, v in params.items()}
    hub_radius = p['hub_radius']
    n_rings = p['n_rings']
    ring_spacing = p['ring_spacing']
    ring_width = p['ring_width']
    n_spokes = p['n_spokes']
    spoke_base_width = p['spoke_base_width']
    spoke_tip_width = p['spoke_tip_width']
    spoke_length = p['spoke_length']

    g = np.zeros((n, n), dtype=bool)
    ci0, ci1, cj0, cj1 = chip
    g[ci0:ci1+1, cj0:cj1+1] = True

    cx = (ci0 + ci1) / 2.0
    cy = (cj0 + cj1) / 2.0

    # Add concentric rings
    for r_idx in range(n_rings):
        radius = hub_radius + r_idx * ring_spacing
        r_in = max(0.0, radius - ring_width / 2.0)
        r_out = radius + ring_width / 2.0
        r_in2 = r_in * r_in
        r_out2 = r_out * r_out
        for i in range(n):
            for j in range(n):
                dx = i - cx
                dy = j - cy
                d2 = dx*dx + dy*dy
                if r_in2 <= d2 <= r_out2:
                    g[i, j] = True

    # Add tapered radial spokes
    for s_idx in range(n_spokes):
        angle = 2 * math.pi * s_idx / n_spokes
        dx = math.cos(angle)
        dy = math.sin(angle)
        for t in range(spoke_length + 1):
            radius = hub_radius + t
            width = spoke_base_width + (spoke_tip_width - spoke_base_width) * (t / spoke_length)
            half_w = width / 2.0
            nx = cx + dx * radius
            ny = cy + dy * radius
            ix_min = math.floor(nx - half_w)
            ix_max = math.ceil(nx + half_w)
            iy_min = math.floor(ny - half_w)
            iy_max = math.ceil(ny + half_w)
            for i in range(int(ix_min), int(ix_max) + 1):
                for j in range(int(iy_min), int(iy_max) + 1):
                    if 0 <= i < n and 0 <= j < n:
                        vx = i - nx
                        vy = j - ny
                        dist_perp = abs(vx * (-dy) + vy * dx)
                        if dist_perp <= half_w + 1e-5:
                            g[i, j] = True

    # Enforce connectivity via flood fill from chip
    visited = np.zeros((n, n), dtype=bool)
    queue = []
    for i in range(ci0, ci1+1):
        for j in range(cj0, cj1+1):
            visited[i, j] = True
            queue.append((i, j))
    while queue:
        i, j = queue.pop(0)
        for di, dj in [(-1,0),(1,0),(0,-1),(0,1)]:
            ni, nj = i+di, j+dj
            if 0 <= ni < n and 0 <= nj < n and not visited[ni,nj] and g[ni,nj]:
                visited[ni,nj] = True
                queue.append((ni,nj))
    g &= visited

    # Enforce minimum feature size (2 cells) via erosion then dilation
    kernel = np.array([[1,1,1],[1,1,1],[1,1,1]], dtype=bool)
    eroded = np.zeros_like(g)
    for i in range(1, n-1):
        for j in range(1, n-1):
            if np.all(g[i-1:i+2, j-1:j+2]):
                eroded[i,j] = True
    dilated = np.zeros_like(g)
    for i in range(1, n-1):
        for j in range(1, n-1):
            if eroded[i,j]:
                for di in [-1,0,1]:
                    for dj in [-1,0,1]:
                        ni, nj = i+di, j+dj
                        if 0 <= ni < n and 0 <= nj < n:
                            dilated[ni,nj] = True
    g = dilated

    # Enforce no enclosed voids: fill holes not connected to boundary
    bg_visited = np.zeros((n, n), dtype=bool)
    bg_queue = []
    for i in [0, n-1]:
        for j in range(n):
            if not g[i,j] and not bg_visited[i,j]:
                bg_visited[i,j] = True
                bg_queue.append((i,j))
    for j in [0, n-1]:
        for i in range(n):
            if not g[i,j] and not bg_visited[i,j]:
                bg_visited[i,j] = True
                bg_queue.append((i,j))
    while bg_queue:
        i, j = bg_queue.pop(0)
        for di, dj in [(-1,0),(1,0),(0,-1),(0,1)]:
            ni, nj = i+di, j+dj
            if 0 <= ni < n and 0 <= nj < n and not g[ni,nj] and not bg_visited[ni,nj]:
                bg_visited[ni,nj] = True
                bg_queue.append((ni,nj))
    holes = ~g & ~bg_visited
    g |= holes

    # Final clip to cell budget
    material_count = np.sum(g)
    max_cells = 1440
    if material_count > max_cells:
        excess = material_count - max_cells
        flat_indices = np.argwhere(g).tolist()
        import random
        random.shuffle(flat_indices)
        for idx in flat_indices[:excess]:
            i, j = idx
            g[i,j] = False

    return g

import numpy as np

def hilbert_curve(order):
    """Generate points of a Hilbert curve of given order."""
    if order == 0:
        return [(0, 0)]
    pts = hilbert_curve(order - 1)
    size = 2 ** (order - 1)
    new_pts = []
    # Bottom-left
    for x, y in pts:
        new_pts.append((y, x))
    # Top-left
    for x, y in pts:
        new_pts.append((x, y + size))
    # Top-right
    for x, y in pts:
        new_pts.append((x + size, y + size))
    # Bottom-right
    for x, y in pts:
        new_pts.append((2 * size - 1 - y, size - 1 - x))
    return new_pts

def thicken_path(points, thickness):
    """Thicken a path of points by given thickness (Manhattan expansion)."""
    if thickness <= 0:
        return set(points)
    thickened = set()
    for (x, y) in points:
        for dx in range(-thickness + 1, thickness):
            for dy in range(-thickness + 1, thickness):
                if abs(dx) + abs(dy) < thickness:
                    thickened.add((x + dx, y + dy))
    return thickened

def generate(params, n, chip):
    # Extract and cast parameters
    center_width = int(params['center_width'])
    turn_spacing = int(params['turn_spacing'])
    min_width = int(params['min_width'])
    max_length = int(params['max_length'])
    order_val = int(params['order'])

    # Ensure minimum values
    center_width = max(2, center_width)
    turn_spacing = max(2, turn_spacing)
    min_width = max(2, min_width)
    max_length = max(1, max_length)
    order_val = max(1, order_val)

    # Limit order to prevent excessive size
    max_order = int(np.log2(n)) + 1
    order_val = min(order_val, max_order)

    # Generate Hilbert curve points
    try:
        points = hilbert_curve(order_val)
    except RecursionError:
        order_val = 1
        points = hilbert_curve(order_val)

    scale = (n - 1) / ((2 ** order_val) - 1) if (2 ** order_val) > 1 else 1
    scaled_points = [(int(x * scale), int(y * scale)) for (x, y) in points]

    # Remove duplicate consecutive points
    unique_points = []
    for p in scaled_points:
        if not unique_points or p != unique_points[-1]:
            unique_points.append(p)
    if len(unique_points) < 2:
        unique_points = [(0, 0), (n-1, n-1)]

    # Thicken the path to ensure minimum width and connectivity
    thickness = max(min_width, center_width // 2)
    material_set = thicken_path(unique_points, thickness)

    # Convert to grid and ensure within bounds
    g = np.zeros((n, n), dtype=bool)
    for (x, y) in material_set:
        if 0 <= x < n and 0 <= y < n:
            g[x, y] = True

    ci0, ci1, cj0, cj1 = chip
    # Ensure chip region is material
    g[ci0:ci1+1, cj0:cj1+1] = True

    # Enforce 4-connectivity from chip via BFS flood fill
    visited = np.zeros_like(g, dtype=bool)
    queue = collections.deque()
    # Start BFS from chip center
    ci_mid = (ci0 + ci1) // 2
    cj_mid = (cj0 + cj1) // 2
    if g[ci_mid, cj_mid]:
        queue.append((ci_mid, cj_mid))
        visited[ci_mid, cj_mid] = True
    else:
        # If chip center not material (shouldn't happen due to above), start from any chip cell
        for i in range(ci0, ci1+1):
            for j in range(cj0, cj1+1):
                if g[i, j]:
                    queue.append((i, j))
                    visited[i, j] = True
                    break
            if queue:
                break

    while queue:
        x, y = queue.popleft()
        for dx, dy in [(-1,0), (1,0), (0,-1), (0,1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < n and g[nx, ny] and not visited[nx, ny]:
                visited[nx, ny] = True
                queue.append((nx, ny))

    # Keep only material connected to chip
    g &= visited

    # Ensure minimum width by dilation (if needed)
    if min_width > 1:
        kernel_size = min_width
        padded = np.pad(g, kernel_size//2, mode='constant', constant_values=False)
        dilated = np.zeros_like(g)
        for i in range(n):
            for j in range(n):
                if np.any(padded[i:i+kernel_size, j:j+kernel_size]):
                    dilated[i, j] = True
        g = dilated
        # Re-ensure connectivity after dilation
        visited = np.zeros_like(g, dtype=bool)
        queue = collections.deque()
        ci_mid = (ci0 + ci1) // 2
        cj_mid = (cj0 + cj1) // 2
        if g[ci_mid, cj_mid]:
            queue.append((ci_mid, cj_mid))
            visited[ci_mid, cj_mid] = True
        else:
            for i in range(ci0, ci1+1):
                for j in range(cj0, cj1+1):
                    if g[i, j]:
                        queue.append((i, j))
                        visited[i, j] = True
                        break
                if queue:
                    break
        while queue:
            x, y = queue.popleft()
            for dx, dy in [(-1,0), (1,0), (0,-1), (0,1)]:
                nx, ny = x + dx, y + dy
                if 0 <= nx < n and 0 <= ny < n and g[nx, ny] and not visited[nx, ny]:
                    visited[nx, ny] = True
                    queue.append((nx, ny))
        g &= visited

    # Enforce max material count by truncating farthest points from chip
    if np.sum(g) > max_length:
        # Distance transform from chip
        dist = np.full((n, n), np.inf)
        queue = collections.deque()
        for i in range(ci0, ci1+1):
            for j in range(cj0, cj1+1):
                if g[i, j]:
                    dist[i, j] = 0
                    queue.append((i, j))
        while queue:
            x, y = queue.popleft()
            for dx, dy in [(-1,0), (1,0), (0,-1), (0,1)]:
                nx, ny = x + dx, y + dy
                if 0 <= nx < n and 0 <= ny < n:
                    if dist[nx, ny] > dist[x, y] + 1:
                        dist[nx, ny] = dist[x, y] + 1
                        queue.append((nx, ny))
        # Flatten and sort by distance
        flat_indices = np.argsort(dist, axis=None)
        # Keep closest points until budget
        keep_count = min(int(max_length), np.sum(g))
        g_flat = g.flatten()
        g_flat[flat_indices[keep_count:]] = False
        g = g_flat.reshape((n, n))
        # Final connectivity check
        visited = np.zeros_like(g, dtype=bool)
        queue = collections.deque()
        ci_mid = (ci0 + ci1) // 2
        cj_mid = (cj0 + cj1) // 2
        if g[ci_mid, cj_mid]:
            queue.append((ci_mid, cj_mid))
            visited[ci_mid, cj_mid] = True
        else:
            for i in range(ci0, ci1+1):
                for j in range(cj0, cj1+1):
                    if g[i, j]:
                        queue.append((i, j))
                        visited[i, j] = True
                        break
                if queue:
                    break
        while queue:
            x, y = queue.popleft()
            for dx, dy in [(-1,0), (1,0), (0,-1), (0,1)]:
                nx, ny = x + dx, y + dy
                if 0 <= nx < n and 0 <= ny < n and g[nx, ny] and not visited[nx, ny]:
                    visited[nx, ny] = True
                    queue.append((nx, ny))
        g &= visited

    # Ensure no enclosed voids by filling holes (simple method: fill any 0 surrounded by 1s)
    # Using flood fill from borders to find background, then holes are non-background zeros
    bg = np.zeros_like(g, dtype=bool)
    queue = collections.deque()
    # Add all border cells
    for i in range(n):
        queue.append((i, 0))
        queue.append((i, n-1))
        queue.append((0, i))
        queue.append((n-1, i))
    while queue:
        x, y = queue.popleft()
        if 0 <= x < n and 0 <= y < n and not g[x, y] and not bg[x, y]:
            bg[x, y] = True
            for dx, dy in [(-1,0), (1,0), (0,-1), (0,1)]:
                nx, ny = x + dx, y + dy
                if 0 <= nx < n and 0 <= ny < n:
                    queue.append((nx, ny))
    # Holes are zeros not in bg
    holes = (~g) & (~bg)
    g |= holes  # Fill holes

    return g
